def require_accepted_audio(result: ProcessingResult) -> AcceptedAudio:
    """Stop a consumer from falling back to rejected original input."""
    if result.accepted_audio is None:
        raise ValueError(f"Downstream processing blocked: {result.status.value}")
    return result.accepted_audio

def training_arrays(pairs):
    xx, yy, ww = [], [], []
    group_counts = defaultdict(int)
    for p in pairs:
        if "excluded" not in p:
            group_counts[p["group"]] += 1
    for p in pairs:
        if "excluded" in p:
            continue
        m, target = p["mask"], p["target"]
        plateau, outside = m & (target != 0), m & (target == 0)
        weight = 1./len(group_counts)/group_counts[p["group"]]
        for view, wanted, region, share in (("A", np.zeros(len(m)), m, .5),
                                            ("C", target, plateau, .35),
                                            ("C", target, outside, .15)):
            if not region.any():
                continue
            xx.append(context_features(p[view]["views"][0], include_boundary=False)[region])
            yy.append(wanted[region])
            ww.append(np.full(int(region.sum()), weight*share/region.sum()))
    if not xx:
        raise ValueError("No audited original-source training pairs")
    return np.concatenate(xx), np.concatenate(yy), np.concatenate(ww)

class CorrectionEncoder(nn.Module):
    def __init__(self, config=ModelConfig()):
        super().__init__()
        self.config = config
        self.project = nn.Linear(config.features, config.hidden)
        layer = nn.TransformerEncoderLayer(config.hidden, config.heads, config.feed_forward, config.dropout, batch_first=True)
        # The nested-tensor fast path can shorten padded outputs; every frame must keep its time position.
        self.encoder = nn.TransformerEncoder(layer, config.layers, enable_nested_tensor=False)
        self.head = nn.Linear(config.hidden, 1)

    def positions(self, length, device):
        position = torch.arange(length, device=device).unsqueeze(1)
        rate = torch.exp(torch.arange(0, self.config.hidden, 2, device=device)*(-math.log(10000.)/self.config.hidden))
        table = torch.zeros(length, self.config.hidden, device=device)
        table[:, 0::2], table[:, 1::2] = torch.sin(position*rate), torch.cos(position*rate)
        return table

    def forward(self, features, padding=None):
        """features: batch x frames x inputs; padding: True where a frame is padding. No causal mask: bidirectional."""
        if features.shape[-1] != self.config.features:
            raise ValueError(f'Expected {self.config.features} input features, got {features.shape[-1]}')
        hidden = self.project(features)+self.positions(features.shape[1], features.device)
        cents = self.head(self.encoder(hidden, src_key_padding_mask=padding)).squeeze(-1)
        return cents if padding is None else cents.masked_fill(padding, 0.)

    def parameter_count(self):
        return sum(parameter.numel() for parameter in self.parameters())

    def describe(self):
        return dict(asdict(self.config), parameters=self.parameter_count())

def squared_objective(r, batch, condition, weights, response):
    """Proposal objective with L_A as masked mean squared error; L_S, L_B, L_D unchanged (mean absolute)."""
    import torch
    from bpdr_input.modeling.losses import smoothness, boundary_invariance, counter_detuning
    mask, det = batch['mask'], batch['detuning']
    m = mask.to(det.dtype); frames = m.sum(1); used = frames > 0
    parts = {}
    def mse(pred, target):
        return ((((pred-target)**2)*m).sum(1)[used]/frames[used]).mean()
    parts['anchor'] = sum(mse(r[v], torch.zeros_like(det) if v in 'AB' else -det) for v in 'ABCD')/4
    parts['smoothness'] = sum(smoothness(r[v], batch['voiced']['A' if v in 'AB' else 'C'])[0] for v in 'ABCD')/4
    total = parts['anchor']+weights.smoothness*parts['smoothness']
    if condition == 'bpdr' and response:
        parts['boundary'] = boundary_invariance(r, mask)[0]; parts['detuning'] = counter_detuning(r, det, mask)[0]
        total = total+weights.boundary*parts['boundary']+weights.detuning*parts['detuning']
    return total, parts

def predict_raw(model, raw71):
    """Uncalibrated physical cents; no reference, target or intervention interval."""
    features = context_features(raw71, include_boundary=False)
    if model["kind"] == "old_mlp":
        from bpdr_input.modeling.local_context_pilot import predict_raw as old_predict
        return old_predict(model["estimator"], raw71)
    output = np.asarray(model["estimator"].predict(features), dtype=np.float64)
    if output.shape != (len(raw71),) or not np.isfinite(output).all():
        raise ValueError("Invalid learned recovery prediction")
    return output

def fixed_metrics(prediction, target, mask, tolerance=10.):
    """Per-case correction error on an unchanged scoring denominator.

    Empty masks or missing predictions are errors, never silently removed.
    Singer aggregation belongs to the caller; frames are not independent people.
    """
    prediction, target, mask = np.asarray(prediction), np.asarray(target), np.asarray(mask)
    if prediction.ndim != 1 or prediction.shape != target.shape or mask.shape != target.shape or mask.dtype != bool:
        raise ValueError("Metric arrays must be aligned 1D arrays and an explicit boolean mask")
    if not mask.any() or not np.isfinite(tolerance) or tolerance <= 0:
        raise ValueError("A nonempty fixed mask and positive finite tolerance are required")
    if not np.isfinite(prediction[mask]).all() or not np.isfinite(target[mask]).all():
        raise ValueError("Missing scored pitch must be reported, not dropped from the denominator")
    error = np.abs(prediction[mask]-target[mask])
    return dict(frames=int(mask.sum()), mae_cents=float(error.mean()),
                within_tolerance_percent=100*float(np.mean(error <= tolerance)))
